  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary: Propagates water from the source outward by BFS, filling pipes whose adjacent pipes
   *          have matching/opposite connection directions, up to the given distance from the source.
   * Algorithm:
   *   1. Initialize currentFilledTiles = 0.
   *   2. For each cell already in filledTiles, expand to neighbours within `distance` using BFS:
   *        a. For each connection direction d of the pipe in the current cell:
   *           - Compute neighbour coordinate n = coord + Pa19Helper.getOffset(d).
   *           - If n is within bounds and points to a FillableCell with a non-null pipe:
   *               * Check that the neighbour's pipe has Pa19Helper.getOpposite(d) among its connections.
   *               * If it does and the neighbour is not already filled, mark it filled, append to filledTiles, and increment currentFilledTiles.
   *   3. After traversal:
   *        - Set prevFilledTiles to the number of tiles filled in this round.
   *        - Set prevFilledDistance to the supplied distance.
   *   4. Optionally update each filled pipe's filled flag for rendering.
   * Related Features: cell : Cell[][], rows : int, cols : int, prevFilledDistance, prevFilledTiles, filledTiles : List<Coordinate>, sourceCell : TerminationCell
   * Related Classes: FillableCell, Pipe, Coordinate, Pa19Helper, Direction
   * Input: distance : int - the BFS depth from the source that water is allowed to reach this round; must be >= 0.
   * Output: void
   * Pre-condition: The map is fully initialized, sourceCell is marked filled (fillBeginTile was called), and filledTiles is non-empty containing the source.
   * Post-condition: All reachable pipes within `distance` from the source (along valid connection pairs) are marked filled, filledTiles reflects the new set, and prevFilledTiles/prevFilledDistance are updated for loss detection.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public void fillTiles(final int distance)
  {
    int currentFilledTiles = 0;
    Pa19Helper helper = Pa19Factory.eINSTANCE.createPa19Helper();
    Set<Coordinate> visited = new HashSet<Coordinate>();
    Queue<Coordinate> queue = new LinkedList<Coordinate>();
    for (Coordinate seed : getFilledTiles())
    {
      visited.add(seed);
      queue.add(seed);
    }
    int depth = 0;
    while (!queue.isEmpty() && depth <= distance)
    {
      int levelSize = queue.size();
      for (int i = 0; i < levelSize; i++)
      {
        Coordinate cur = queue.poll();
        Cell curCell = getCell()[cur.getRow()][cur.getCol()];
        Pipe pipe = null;
        if (curCell instanceof FillableCell)
        {
          pipe = ((FillableCell) curCell).getPipe();
        }
        if (pipe == null)
        {
          continue;
        }
        for (Direction d : pipe.getConnections())
        {
          Coordinate offset = helper.getOffset(d);
          if (offset == null)
          {
            continue;
          }
          Coordinate neighbour = cur.add(offset);
          int nr = neighbour.getRow();
          int nc = neighbour.getCol();
          if (nr < 0 || nr >= getRows() || nc < 0 || nc >= getCols())
          {
            continue;
          }
          Cell nCell = getCell()[nr][nc];
          if (!(nCell instanceof FillableCell))
          {
            continue;
          }
          Pipe neighbourPipe = ((FillableCell) nCell).getPipe();
          if (neighbourPipe == null)
          {
            continue;
          }
          Direction opposite = helper.getOpposite(d);
          if (opposite == null || !neighbourPipe.getConnections().contains(opposite))
          {
            continue;
          }
          if (!visited.contains(neighbour))
          {
            visited.add(neighbour);
            getFilledTiles().add(neighbour);
            neighbourPipe.setFilled(true);
            currentFilledTiles++;
            queue.add(neighbour);
          }
        }
      }
      depth++;
    }
    this.prevFilledTiles = currentFilledTiles;
    this.prevFilledDistance = distance;
  }

